// Fira Sans Condensed (subset, OFL license) for jsPDF card rendering
window.CARD_FONTS = {
  "Regular": "",
  "Bold": "",
  "Italic": "",
  "BoldItalic": "",
};
window.registerCardFonts = function (doc) {
  const styles = { Regular: "normal", Bold: "bold", Italic: "italic", BoldItalic: "bolditalic" };
  for (const [st, js] of Object.entries(styles)) {
    const f = "FiraSansCondensed-" + st + ".ttf";
    doc.addFileToVFS(f, window.CARD_FONTS[st]);
    doc.addFont(f, "FiraCond", js);
  }
};